actions.script:
const workspace = sri.buildUrl('../Workspace').path
const parts = String(context.treeOpenPath || '').split('/').filter((part) => part)
const openDirs = new Set(parts.slice(0, -1).map((part, index) => parts.slice(0, index + 1).join('/')))
const nodesOf = (dir) => {
    const out = ec.service.sync().name('org.moqui.devaide.WorkspaceServices.list#Directory').parameters({rootId: rootId, path: dir}).call()
    if (ec.message.hasError()) return null
    return Array.from((out && out.entries) || []).map((entry) => {
        const relative = dir ? dir + '/' + entry.name : entry.name
        // a directory's ignored mark is rolled up from what is in it, so only a file's is shown
        const text = (entry.status ? entry.status + ' ' : '') + entry.name + (entry.dir ? '/' : '') + (entry.ignored && !entry.dir ? ' (ignored)' : '')
        if (entry.dir) return {id: relative, text: text, children: (openDirs.has(relative) && nodesOf(relative)) || true}
        return {id: relative, text: text, children: false,
            a_attr: {urlText: workspace + '?rootId=' + encodeURIComponent(rootId || '') + '&path=' + encodeURIComponent(relative)}}
    })
}
const node = String(context.treeNodeId || '#')
const nodes = nodesOf(node === '#' ? '' : node)
if (nodes == null) {
    const errors = ec.message.errorsString
    ec.message.clearErrors()
    ec.web.sendJsonResponse({errors: errors})
} else {
    ec.web.sendJsonResponse(nodes)
}

const files = Array.from((ec.service.sync().name('org.moqui.devaide.WorkspaceServices.find#Files').parameters({rootId: rootId}).call() || {}).files || [])
const term = String(context.term || '').trim().toLowerCase()
const words = term.split(/\s+/).filter((word) => word)
const nameOf = (file) => file.split('/').pop().toLowerCase()
const hits = files.filter((file) => words.every((word) => file.toLowerCase().includes(word)))
hits.sort((left, right) => (nameOf(left).includes(term) ? 0 : 1) - (nameOf(right).includes(term) ? 0 : 1) || left.length - right.length)
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(errors ? {errors: errors} : {options: hits.slice(0, 50).map((file) => ({value: file, label: file}))})

const conflictKey = 'DevAideTui.conflict'
let text = context.fileText
let base = context.baseHash
let ready = true
if (String(context.overDisk) === 'true') {
    let kept = null
    try { kept = JSON.parse(ec.web.sessionAttributes[conflictKey] || 'null') } catch (e) { kept = null }
    if (!kept || kept.rootId !== rootId || kept.path !== path) {
        ec.message.addError(ec.l10n.localize('Nothing to save over the disk: open the file and save it again'))
        ready = false
    } else {
        text = kept.text
        base = kept.diskHash
    }
}
if (ready) {
    ec.web.sessionAttributes.remove(conflictKey)
    const out = ec.service.sync().name('org.moqui.devaide.WorkspaceServices.save#File').parameters({rootId: rootId, path: path,
        text: String(text ?? ''), baseHash: String(base || '')}).call() || {}
    if (!ec.message.hasError() && out.conflict) {
        ec.web.sessionAttributes[conflictKey] = JSON.stringify({rootId: rootId, path: path, text: String(text ?? ''),
            diskHash: out.diskHash || '', diskText: out.diskText || ''})
        ec.message.addMessage(path + ' ' + ec.l10n.localize('changed on disk since it was opened: compare them below'), 'warning')
    } else if (!ec.message.hasError()) {
        const files = Array.from((out.reload && out.reload.files) || [])
        const problems = Array.from(out.problems || [])
        const summary = files.map((file) => file.summary).filter((one) => one).join('; ')
        ec.message.addMessage(ec.l10n.localize('Saved') + (summary ? ' · ' + summary : '') + (out.reload ? ' · ' + out.reload.millis + ' ms' : ''),
            problems.some((problem) => problem.severity === 'error') ? 'warning' : 'success')
        const ddl = files.flatMap((file) => Array.from(file.ddl || []))
        if (ddl.length) ec.message.addMessage(ec.l10n.localize('DDL run') + ': ' + ddl.join('; '), 'info')
        if (out.rebuild) ec.message.addMessage(ec.l10n.localize('A change needs a rebuild (./moq build) and a restart'), 'warning')
        else if (out.restart) ec.message.addMessage(ec.l10n.localize('A change needs a restart to apply'), 'warning')
        if (out.restart || out.rebuild) ec.web.sessionAttributes['DevAideTui.restart'] = 'true'
        ec.web.sessionAttributes['DevAideTui.problems'] = JSON.stringify({rootId: rootId, path: path, hash: out.hash || '', problems: problems})
    }
}

const file = ec.service.sync().name('org.moqui.devaide.WorkspaceServices.get#File').parameters({rootId: rootId, path: path}).call() || {}
if (!ec.message.hasError()) {
    const problems = Array.from((ec.service.sync().name('org.moqui.devaide.WorkspaceServices.check#File')
        .parameters({rootId: rootId, path: path, text: file.text || ''}).call() || {}).problems || [])
    if (!ec.message.hasError()) {
        ec.web.sessionAttributes['DevAideTui.problems'] = JSON.stringify({rootId: rootId, path: path, hash: file.hash || '', problems: problems})
        ec.message.addMessage(problems.length ? problems.length + ' ' + ec.l10n.localize('problems') : ec.l10n.localize('No problems'),
            problems.length ? 'warning' : 'success')
    }
}

const lastLine = (text) => String(text || '').trim().split(/\r?\n/).pop()
const out = ec.service.sync().name('org.moqui.devaide.VcsServices.commit#Changes').parameters({rootId: rootId, summary: context.summary || '',
    body: context.body || '', task: context.task || '', amend: String(context.amend) === 'true', signOff: String(context.signOff) === 'true'}).call() || {}
if (!ec.message.hasError()) {
    ec.message.addMessage(ec.l10n.localize('Committed') + ' ' + String(out.commitId || '').slice(0, 9), 'success')
    if (context.commitPushButton) {
        const pushed = ec.service.sync().name('org.moqui.devaide.VcsServices.push#Remote').parameters({rootId: rootId}).call() || {}
        if (!ec.message.hasError()) ec.message.addMessage(pushed.message || (ec.l10n.localize('Pushed') + (pushed.output ? ': ' + lastLine(pushed.output) : '')), 'success')
    }
    changePath = null
}

const verbs = {fetch: 'fetch#Remote', pull: 'pull#Remote', push: 'push#Remote'}
const done = {fetch: 'Fetched', pull: 'Pulled', push: 'Pushed'}
if (!verbs[context.command]) {
    ec.message.addError(ec.l10n.localize('Unknown git command') + ': ' + (context.command || ''))
} else {
    const out = ec.service.sync().name('org.moqui.devaide.VcsServices.' + verbs[context.command]).parameters({rootId: rootId}).call() || {}
    if (!ec.message.hasError()) {
        const last = String(out.output || '').trim().split(/\r?\n/).pop()
        ec.message.addMessage(out.message || (ec.l10n.localize(done[context.command]) + (last ? ': ' + last : '')), 'success')
        if (out.extensionsAffected) ec.message.addMessage(out.extensionsAffected + ' ' +
            ec.l10n.localize('site extensions are affected: see Artifacts › Customizations'), 'warning')
    }
}

const verbs = {cherryPick: 'cherryPick#Commit', revert: 'revert#Commit'}
if (!verbs[context.replay]) {
    ec.message.addError(ec.l10n.localize('Unknown action') + ': ' + (context.replay || ''))
} else {
    const out = ec.service.sync().name('org.moqui.devaide.VcsServices.' + verbs[context.replay]).parameters({rootId: rootId, commitId: commitId}).call() || {}
    if (!ec.message.hasError()) ec.message.addMessage(out.conflict
        ? ec.l10n.localize('It stopped at conflicts: resolve them in the browser\'s Workspace')
        : ec.l10n.localize(context.replay === 'revert' ? 'Reverted' : 'Cherry-picked') + ' ' + String(commitId || '').slice(0, 9),
        out.conflict ? 'warning' : 'success')
}

// A read for the page: its answer, or null with its errors kept for the page to show.
loadErrors = []
const read = (name, parameters) => {
    const out = ec.service.sync().name(name).parameters(parameters).requireNewTransaction(true).call()
    if (ec.message.hasError()) { loadErrors.push(ec.message.errorsString); ec.message.clearErrors(); return null }
    return out || {}
}
const kept = (key) => { try { return JSON.parse(ec.web.sessionAttributes[key] || 'null') } catch (e) { return null } }
const workspaceUrl = (parameters) => sri.buildUrl('../Workspace').addParameters(Object.fromEntries(Object.entries(parameters)
    .filter(([, value]) => value != null && value !== ''))).getUrlWithParams()
const diffText = (original, modified, from, to) => String(ec.resource.textDiff(original || '', modified || '', from, to).unifiedDiff || '')

// the root, the user's tier, and whether this user may write here (the services decide; this only hides)
const rootsOut = read('org.moqui.devaide.WorkspaceServices.get#Roots', {}) || {}
const roots = Array.from(rootsOut.roots || [])
tier = rootsOut.tier || 'view'
root = roots.find((one) => one.id === rootId) || (rootId ? null : roots[0]) || null
rootMissing = !!rootId && !root
rootId = root ? root.id : rootId
rootOptions = roots.map((one) => ({id: one.id, label: one.label + (one.kind === 'git' ? '' : ' (directory)') + (one.readOnly ? ' (read only)' : '')}))
rootValues = {rootId: rootId, tab: tab || 'code'}
isGit = !!root && root.kind === 'git' && rootsOut.gitAvailable !== false
canWrite = !!root && tier !== 'view' && !root.readOnly
tab = ['code', 'changes', 'commits'].includes(tab) ? tab : 'code'
restartNeeded = ec.web.sessionAttributes['DevAideTui.restart'] === 'true'

// the header: the branch, ahead and behind, the changes; and the tabs
status = root && isGit ? read('org.moqui.devaide.VcsServices.get#Status', {rootId: rootId}) : null
const entries = Array.from((status && status.entries) || [])
branchText = status ? (status.branch || '(detached)') + (status.upstream ? ' → ' + status.upstream : '') : ''
aheadText = status && (status.ahead || status.behind) ? '↑' + (status.ahead || 0) + ' ↓' + (status.behind || 0) : ''
changesText = status ? entries.length + ' ' + ec.l10n.localize('changed') : ''
headerText = [branchText, aheadText, changesText].filter((part) => part).join('   ')
operationText = status && status.operation ? ec.l10n.localize('A ' + status.operation + ' stopped at conflicts: resolve it in the browser\'s Workspace') : ''
branchOptions = Array.from((status && status.branches) || []).filter((branch) => !branch.current)
    .map((branch) => ({name: branch.name, label: branch.name + (branch.upstream ? ' → ' + branch.upstream : '')}))
tabItems = [['code', 'Code'], ['changes', 'Changes'], ['commits', 'Commits']].map(([key, title]) => ({title: ec.l10n.localize(title),
    url: workspaceUrl({rootId: rootId, tab: key, path: key === 'code' ? path : null, line: key === 'code' ? line : null}), active: tab === key}))

// ---- Code ----
file = null
if (tab === 'code' && root && path) file = read('org.moqui.devaide.WorkspaceServices.get#File', {rootId: rootId, path: path})
const language = {xml: 'xml', xsd: 'xml', qvue: 'xml', qvt: 'xml', vue: 'xml', html: 'xml', htm: 'xml', js: 'js', mjs: 'js', cjs: 'js', ts: 'js',
    json: 'json', sql: 'sql', md: 'md'}[String(path || '').split('/').pop().split('.').pop().toLowerCase()] || 'plain'
hasText = !!file && file.text != null
fileReadOnly = !file || !!file.readOnly || !canWrite
fileLine = (root ? root.label : '') + ' › ' + (path || '') + (file && file.status ? ' · ' + file.status : '')
    + (file && file.readOnly ? ' · ' + ec.l10n.localize('read only') + (file.readOnlyReason ? ': ' + file.readOnlyReason : '') : '')
fileValues = {rootId: rootId, path: path, baseHash: file ? file.hash : '', fileText: hasText ? file.text : ''}
// the artifacts the file defines, for the File menu's References: an index that cannot answer leaves none
fileArtifacts = []
if (file) {
    const inFile = ec.service.sync().name('org.moqui.devaide.ArtifactServices.get#ArtifactsInFile')
        .parameters({rootId: rootId, path: path}).requireNewTransaction(true).call()
    if (ec.message.hasError()) {
        ec.logger.warn('The artifacts of ' + path + ': ' + ec.message.errorsString)
        ec.message.clearErrors()
    } else {
        fileArtifacts = Array.from((inFile && inFile.artifacts) || []).map((artifact) => ({artifactId: artifact.id,
            artifactLabel: artifact.shortName || artifact.name || artifact.id, artifactKind: artifact.kind || ''}))
    }
}
oneArtifactId = fileArtifacts.length === 1 ? fileArtifacts[0].artifactId : ''
// the problems of the last save or Check of this file, while the file is as it was then
const keptProblems = kept('DevAideTui.problems')
const problemList = file && keptProblems && keptProblems.rootId === rootId && keptProblems.path === path && keptProblems.hash === file.hash
    ? Array.from(keptProblems.problems || []) : []
problemRows = problemList.map((problem) => ({line: problem.line || '', severity: problem.severity || 'error', message: problem.message || '',
    lineUrl: problem.line ? workspaceUrl({rootId: rootId, path: path, line: String(problem.line)}) : ''}))
editor = hasText ? {t: 'component', id: 'WorkspaceEditor', name: 'code', props: {text: file.text, language: language, readOnly: fileReadOnly,
    cursorLine: Number(line) || 1, form: 'WorkspaceFile', field: 'fileText', check: 'checkText', complete: language === 'xml' ? 'schemaDigest' : '',
    parameters: {rootId: rootId, path: path}, problems: problemList.filter((problem) => problem.line > 0)
        .map((problem) => ({line: problem.line, column: problem.column || 0, severity: problem.severity, message: problem.message}))}} : null
// a conflict a save kept for this file: the disk's text against the one saved
const conflict = kept('DevAideTui.conflict')
conflictDiff = file && conflict && conflict.rootId === rootId && conflict.path === path
    ? diffText(conflict.diskText, conflict.text, 'disk/' + path, 'mine/' + path) || ec.l10n.localize('The texts are the same') : ''
fileDiff = ''
if (file && diff === 'Y' && isGit) {
    const sides = read('org.moqui.devaide.VcsServices.get#Diff', {rootId: rootId, path: path})
    fileDiff = sides ? diffText(sides.original, sides.modified, 'a/' + path, 'b/' + path) || ec.l10n.localize('No changes') : ''
}
treeNode = root && tab === 'code' ? {t: 'tree', id: 'WorkspaceFileTree', url: sri.buildUrl('fileTree').path, parameters: {rootId: rootId},
    openPath: path || ''} : null
hitRows = []
hitsTruncated = false
if (tab === 'code' && root && query) {
    const found = read('org.moqui.devaide.WorkspaceServices.search#Files', {rootId: rootId, query: query, regex: regex === 'true'})
    hitRows = Array.from((found && found.results) || []).map((hit) => ({hitText: hit.path + ':' + hit.line, text: String(hit.text || '').trim(),
        hitPath: hit.path, hitLine: String(hit.line)}))
    hitsTruncated = !!(found && found.truncated)
}
searchValues = {rootId: rootId, tab: 'code', path: path, query: query, regex: regex}

// ---- Changes ----
changeRows = entries.map((entry) => ({path: entry.path, letter: entry.letter,
    stateText: entry.conflicted ? ec.l10n.localize('conflicted') : entry.untracked ? ec.l10n.localize('new')
        : entry.staged && entry.unstaged ? ec.l10n.localize('staged, changed since') : entry.staged ? ec.l10n.localize('staged') : ec.l10n.localize('changed'),
    diffStaged: entry.staged && !entry.unstaged ? 'true' : '', bothSides: !!(entry.staged && entry.unstaged)}))
changeDiff = ''
if (tab === 'changes' && isGit && changePath) {
    const sides = read('org.moqui.devaide.VcsServices.get#Diff', {rootId: rootId, path: changePath, staged: staged === 'true'})
    changeDiff = sides ? diffText(sides.original, sides.modified, 'a/' + changePath, 'b/' + changePath) || ec.l10n.localize('No changes') : ''
}
commitValues = {rootId: rootId, task: (status && status.currentTask) || ''}
agreement = tab === 'changes' && isGit && root.hosted ? read('org.moqui.devaide.HostingServices.get#Agreement', {rootId: rootId}) : null
agreementNeeded = !!(agreement && agreement.required && !agreement.signed)

// ---- Commits ----
logPage = Math.max(0, parseInt(pageIndex || '0', 10) || 0)
commitRows = []
logMore = false
if (tab === 'commits' && isGit) {
    const log = read('org.moqui.devaide.VcsServices.get#Log', {rootId: rootId, pageIndex: logPage, pageSize: 100})
    const commits = Array.from((log && log.commits) || [])
    logMore = commits.length === 100
    commitRows = commits.map((commit) => ({id: commit.id, subject: commit.subject || '', shortId: commit.shortId,
        authorName: commit.authorName, dateText: commit.date ? ec.l10n.format(new Date(commit.date), 'yyyy-MM-dd HH:mm') : ''}))
}
commit = null
commitFiles = []
commitDiff = ''
if (tab === 'commits' && isGit && commitId) {
    commit = read('org.moqui.devaide.VcsServices.get#Commit', {rootId: rootId, commitId: commitId})
    commitFiles = Array.from((commit && commit.files) || []).map((one) => ({status: one.status, filePath: one.path}))
    if (commit && commitPath) {
        const sides = read('org.moqui.devaide.VcsServices.get#Diff', {rootId: rootId, path: commitPath, commitId: commitId})
        commitDiff = sides ? diffText(sides.original, sides.modified, 'a/' + commitPath, 'b/' + commitPath) || ec.l10n.localize('No changes') : ''
    }
}
commitTitle = commit && commit.commit ? commit.commit.shortId + ' ' + commit.commit.subject : String(commitId || '').slice(0, 9)
commitByline = commit && commit.commit ? commit.commit.authorName + ' <' + commit.commit.authorEmail + '> · '
    + (commit.commit.date ? ec.l10n.format(new Date(commit.commit.date), 'yyyy-MM-dd HH:mm') : '') : ''
